CREATE FUNCTION deny_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable event history cannot be changed'; END; $$;
CREATE TRIGGER "AttendanceEvent_immutable" BEFORE UPDATE OR DELETE ON "AttendanceEvent" FOR EACH ROW EXECUTE FUNCTION deny_immutable_change();
CREATE TRIGGER "Submission_immutable" BEFORE UPDATE OR DELETE ON "Submission" FOR EACH ROW EXECUTE FUNCTION deny_immutable_change();
CREATE TRIGGER "Review_immutable" BEFORE UPDATE OR DELETE ON "Review" FOR EACH ROW EXECUTE FUNCTION deny_immutable_change();
CREATE TRIGGER "Audit_immutable" BEFORE UPDATE OR DELETE ON "Audit" FOR EACH ROW EXECUTE FUNCTION deny_immutable_change();
CREATE TRIGGER "ReportRevision_immutable" BEFORE UPDATE OR DELETE ON "ReportRevision" FOR EACH ROW EXECUTE FUNCTION deny_immutable_change();
